    "path": "tests/test_datekit.py",
    "content": "import unittest
from datekit import parse_date, add_months, get_fiscal_period

class TestDatekit(unittest.TestCase):
    def test_parse_date(self):
        date = parse_date('2027-01-31')
        self.assertEqual(date, '2027-01-31')

    def test_add_months(self):
        new_date = add_months('2027-01-31', 1)
        self.assertEqual(new_date, '2027-02-28')

    def test_non_existent_date(self):
        with self.assertRaises(ValueError):
            parse_date('2027-02-30')

    def test_fiscal_period(self):
        due_date = parse_date('2027-01-31')
        fiscal_period = get_fiscal_period(due_date)
        self.assertEqual(fiscal_period, '[FY27-P03]')

if __name__ == '__main__':
    unittest.main()
